package com.circaso.designsystem.coins

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/** One painted path of a mono coin mark, in the set's 24 × 24 box (generated by `scripts/coin-icons/generate.py`). */
internal data class IconPath(val d: String, val evenOdd: Boolean = false, val alpha: Float = 1f)

/**
 * How a coin's symbol becomes an icon key (decision 2026-11-06: Web3 Icons mono, themed). The server's set is keyed
 * by upper-case symbol and only answers `[A-Z0-9.]{1,15}`; wrapped, bridged and renamed coins wear their original's
 * mark, so they need no icon of their own.
 */
object CoinSymbols {
    private val Allowed = Regex("[A-Z0-9.]{1,15}")

    private val Aliases = mapOf(
        "WETH" to "ETH",
        "MATIC" to "POL",
        "WMATIC" to "POL",
        "WPOL" to "POL",
        "CBBTC" to "BTC",
        "CIRBTC" to "BTC",
        "WSOL" to "SOL",
        "WAVAX" to "AVAX",
        "USDC.E" to "USDC",
        "USDBC" to "USDC",
    )

    /** The icon key for [symbol] ("weth" → "ETH", "@usdc" → "USDC"), or null when it can't be one. */
    fun normalise(symbol: String): String? {
        val s = symbol.trim().removePrefix("@").uppercase()
        if (!Allowed.matches(s)) return null
        return Aliases[s] ?: s
    }

    /** The network mark for a Circle blockchain id ("BASE-SEPOLIA" → "base"), or null for one we don't draw. */
    fun network(blockchain: String): String? {
        val up = blockchain.trim().uppercase()
        return when {
            up.startsWith("BASE") -> "base"
            up.startsWith("MATIC") || up.startsWith("POLYGON") || up.startsWith("POL-") || up == "POL" -> "polygon"
            up.startsWith("ETH") -> "ethereum"
            up.startsWith("SOL") -> "solana"
            up.startsWith("AVAX") || up.startsWith("AVALANCHE") -> "avalanche"
            up.startsWith("ARB") -> "arbitrum"
            up.startsWith("ARC") -> "arc"
            else -> null
        }
    }

    /** True when the mark ships with the app (instant, offline); otherwise it comes from the server. */
    fun isBundled(key: String): Boolean = key in BundledCoinPaths
}

private val coinVectors = HashMap<String, ImageVector>()
private val networkVectors = HashMap<String, ImageVector>()

/** The bundled mark for an icon key, built once (composition is single-threaded). */
internal fun bundledCoinVector(key: String): ImageVector? =
    coinVectors[key] ?: BundledCoinPaths[key]?.let { vectorOf("coin-$key", it) }?.also { coinVectors[key] = it }

internal fun bundledNetworkVector(key: String): ImageVector? =
    networkVectors[key] ?: BundledNetworkPaths[key]?.let { vectorOf("network-$key", it) }?.also { networkVectors[key] = it }

/** Painted black and recoloured by the caller's tint, so one vector serves every theme. */
private fun vectorOf(name: String, paths: List<IconPath>): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).apply {
        paths.forEach { p ->
            addPath(
                pathData = addPathNodes(p.d),
                pathFillType = if (p.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = SolidColor(Color.Black),
                fillAlpha = p.alpha,
            )
        }
    }.build()
